from pathlib import Path
import re
p=Path('E:/cxy/09-设计与原型/自定义活动管理/custom-activity.html')
s=p.read_text(encoding='utf-8')
replacement='''<div style="margin-top:24px"><h2>选择商品</h2><button type="button" class="link" id="select-products">＋选择商品</button><span id="product-count" style="margin-left:12px">已选0个商品</span><div id="product-picker" hidden style="padding:16px;border:1px solid var(--p-line);margin-top:12px"><small>演示商品，正式系统中从商品档案选择。</small><div id="product-options" style="margin:12px 0"></div><div class="row"><button type="button" id="product-confirm">确认选择</button><button type="button" id="product-cancel">取消</button></div></div><div class="table-wrap"><table><thead><tr><th>序号</th><th>商品名称</th><th>商品编码</th><th>规格</th><th>单位</th><th>操作</th></tr></thead><tbody id="product-rows"><tr><td colspan="6" style="text-align:center">暂无数据，请选择商品</td></tr></tbody></table></div></div>'''
s,n=re.subn(r'<details><summary>关联商品或原审批单（按需填写）</summary>.*?</details>',replacement,s,flags=re.S)
assert n==1
script='''(()=>{const root=document.getElementById('custom-activity'),q=s=>root.querySelector(s);const catalog=[{code:'DEMO-SKU001',name:'示例商品 · 柠檬无骨鸡爪',spec:'158g',unit:'袋'},{code:'DEMO-SKU002',name:'示例商品 · 香辣虎皮凤爪',spec:'105g',unit:'袋'},{code:'DEMO-SKU003',name:'示例商品 · 藤椒贡菜无骨鸭掌',spec:'220g',unit:'盒'}];let selected=[];function draw(){q('#product-count').textContent='已选'+selected.length+'个商品';const tb=q('#product-rows');tb.replaceChildren();if(!selected.length){const tr=document.createElement('tr'),td=document.createElement('td');td.colSpan=6;td.textContent='暂无数据，请选择商品';td.style.textAlign='center';tr.append(td);tb.append(tr)}selected.forEach((p,i)=>{const tr=document.createElement('tr');[i+1,p.name,p.code,p.spec,p.unit].forEach(value=>{const td=document.createElement('td');td.textContent=value;tr.append(td)});const td=document.createElement('td'),b=document.createElement('button');b.type='button';b.textContent='删除';b.className='delete';b.onclick=()=>{selected=selected.filter(v=>v.code!==p.code);draw()};td.append(b);tr.append(td);tb.append(tr)})}q('#select-products').onclick=()=>{q('#product-picker').hidden=false;const opts=q('#product-options');opts.replaceChildren();catalog.forEach(p=>{const label=document.createElement('label');label.className='check';const c=document.createElement('input');c.type='checkbox';c.value=p.code;c.checked=selected.some(v=>v.code===p.code);label.append(c,document.createTextNode(p.name+' / '+p.spec+' / '+p.code));opts.append(label)})};q('#product-cancel').onclick=()=>{q('#product-picker').hidden=true};q('#product-confirm').onclick=()=>{const codes=Array.from(q('#product-options').querySelectorAll('input:checked')).map(e=>e.value);selected=catalog.filter(p=>codes.includes(p.code));draw();q('#product-picker').hidden=true}})();'''
s+='\n<script>'+script+'</script>'
p.write_text(s,encoding='utf-8')
Path('E:/cxy/09-设计与原型/自定义活动管理/自定义活动申请.html').write_text('<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>自定义活动申请</title><body style="margin:16px">'+s+'</body></html>',encoding='utf-8')
